process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
import { chromium } from 'playwright';
import fs from 'fs';
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const A=Buffer.from('','base64').toString();
async function put(path, buf, msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'m', content:buf.toString('base64')};
  if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
async function main(){
  const out={};
  fs.writeFileSync('/tmp/a.html', A);
  const br=await chromium.launch();
  const p=await (await br.newContext({viewport:{width:1400,height:1250}})).newPage();
  await p.goto('file:///tmp/a.html',{waitUntil:'networkidle'});
  await p.waitForTimeout(500);
  await p.fill('#pav','Josera Sensiplus sausas maistas šunims su antiena, 12,5 kg');
  await p.selectOption('#kat','maistas');
  await p.waitForTimeout(400);
  out.spalvos=await p.evaluate(()=>{
    const g=s=>{const e=document.querySelector(s);return e?getComputedStyle(e).color:null;};
    return {etikete:g('.laukas label'), pastaba:g('.pastaba'), sml:g('.sml'), blk_antr:g('.blk-antr')};
  });
  await p.screenshot({path:'/tmp/t1.png',fullPage:true});
  await p.evaluate(()=>{ document.getElementById('b-toliau').click(); });
  await p.waitForTimeout(600);
  await p.evaluate(()=>{ pvzTekstas(); });
  await p.waitForTimeout(300);
  await p.evaluate(()=>{ skaidyti(); });
  await p.waitForTimeout(1200);
  await p.evaluate(()=>{ const k=document.querySelector('#siulymai .kodel'); if(k) k.click(); });
  await p.waitForTimeout(300);
  await p.screenshot({path:'/tmp/t2.png',fullPage:true});
  await br.close();
  for(const f of ['t1','t2']){ try{ await put('screenshots/'+f+'.png', fs.readFileSync('/tmp/'+f+'.png'), f); }catch(e){} }
  await put('analize/tamsu.json', Buffer.from(JSON.stringify(out,null,2)),'t');
}
main().catch(async e=>{ await put('analize/tamsu.json',Buffer.from(JSON.stringify({klaida:String(e)})),'err'); });
